"""List audit chunks under each repo's .punt-labs/ethos/sessions that hold a line json cannot parse."""
import json
import pathlib
import sys

root = pathlib.Path(sys.argv[1])
for repo in sorted([root, *[p for p in root.iterdir() if (p / ".git").exists()]]):
    sess = repo / ".punt-labs" / "ethos" / "sessions"
    if not sess.is_dir():
        continue
    bad = []
    for chunk in sorted(sess.glob("*/*.jsonl")):
        with chunk.open("rb") as fh:
            for n, raw in enumerate(fh, 1):
                if not raw.strip():
                    continue
                try:
                    json.loads(raw)
                except ValueError as exc:
                    bad.append(f"{chunk.relative_to(repo)}:{n}: {exc}")
                    break
    orphans = sorted(str(p.relative_to(repo)) for p in sess.glob("*/*.corrupt"))
    if bad or orphans:
        print(f"== {repo.name}: {len(bad)} corrupt, {len(orphans)} .corrupt files")
        for b in bad:
            print("  ", b)
        for o in orphans:
            print("   orphan", o)

